/* ============================================================
   EXPLICACIONES — lote 17  (48 preguntas teóricas)
   PRIMER lote de preguntas SIN caso clinico. Todas proceden del
   bloque con IDs -P-, que es el examen FIR (Farmaceutico Interno
   Residente) y estaba etiquetado en bloque como "Farmacologia".
   De las 55 que saco el selector se descartaron 7 por ser materia
   de farmacia pura y no de residencia medica (dosis de choque con
   factor de acumulacion, estimacion de aclaramiento en insuficiencia
   renal, eficiencia de disolucion, farmacoeconomia y duplicados).
   Las 48 restantes se reclasifican aqui a su especialidad real:
   Farmacologia de verdad, Ciencias Basicas o Medicina Interna.
   ============================================================ */
window.EXPLICACIONES = Object.assign(window.EXPLICACIONES || {}, {

/* ==================== FARMACOCINÉTICA APLICADA ==================== */
'MIR-2013-P109': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Biodisponibilidad',
  clave:'Biodisponibilidad ABSOLUTA: fracción que llega inalterada a la circulación sistémica comparada con la MISMA dosis intravenosa.',
  exp:'La biodisponibilidad mide *cuánto* del fármaco administrado llega intacto a la sangre y *a qué velocidad*. Lo que convierte a una biodisponibilidad en *absoluta* es el patrón con el que se compara: la *vía intravenosa*, que por definición tiene una biodisponibilidad del 100% porque el fármaco entra directamente en la circulación sin barreras. De ahí el cálculo: se compara el área bajo la curva de la forma estudiada con el área bajo la curva de la misma dosis por vía intravenosa. Si en cambio la comparación se hace frente a *otro preparado del mismo principio activo* —por ejemplo un genérico frente a la marca original— la biodisponibilidad es *relativa*, y ese es el fundamento de los estudios de *bioequivalencia*. El concepto tiene una consecuencia clínica directa: explica por qué la dosis oral y la intravenosa de un mismo fármaco no coinciden. Los dos factores que la reducen son la *absorción incompleta* y el *efecto de primer paso* hepático e intestinal, y por eso fármacos con primer paso intenso, como el propranolol o la morfina, necesitan dosis orales mucho mayores que las parenterales.',
  no:{0:'La biofase es el lugar donde el fármaco actúa, no la circulación sistémica: no es lo que se mide.',1:'Comparar con un preparado patrón que no sea intravenoso define la biodisponibilidad RELATIVA.',3:'Que llegue el 100% es lo que ocurre por definición en la vía intravenosa, no la definición del término.',4:'El lugar de absorción es previo a la circulación: lo que se mide es lo que llega a la sangre.'},
  trampa:'Se confunden absoluta y relativa. La palabra clave es con qué se compara: intravenosa da absoluta, otro preparado da relativa.',
  dx:[],
  obj:'Definir la biodisponibilidad absoluta y diferenciarla de la relativa.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P117': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Estado estacionario',
  clave:'La CONCENTRACIÓN en el equilibrio depende de la velocidad de infusión y del aclaramiento. El TIEMPO en alcanzarlo depende solo de la semivida.',
  exp:'En una perfusión continua hay que separar dos preguntas que se confunden todo el rato. La primera es *a qué altura* queda la meseta, y la responde una fórmula sencilla: la concentración en estado estacionario es igual a la *velocidad de infusión dividida entre el aclaramiento*. Es decir, depende de esas dos cosas y solo de esas dos: si se dobla la velocidad de infusión, la meseta se dobla; si el aclaramiento cae a la mitad —por ejemplo en un paciente con insuficiencia renal—, la meseta se dobla también. La segunda pregunta es *cuánto se tarda* en llegar, y esa depende exclusivamente de la *semivida de eliminación*: cuatro o cinco semividas, con independencia de la velocidad de infusión y de la dosis. De ahí las dos consecuencias prácticas: para *cambiar el nivel* alcanzado se ajusta la velocidad de infusión, y para *llegar antes* no sirve de nada subirla, hay que administrar una *dosis de carga*.',
  no:{0:'La concentración depende del aclaramiento Y de la velocidad de infusión: decir "exclusivamente del aclaramiento" es incompleto.',1:'El tiempo hasta el equilibrio depende de la semivida, no del volumen de distribución de forma aislada.',2:'La semivida gobierna el TIEMPO, no la concentración alcanzada.',4:'El tiempo no depende del aclaramiento aislado sino de la semivida, que combina aclaramiento y volumen de distribución.'},
  trampa:'Se mezcla la altura de la meseta con el tiempo en alcanzarla. Altura: velocidad de infusión y aclaramiento. Tiempo: semivida.',
  dx:[],
  obj:'Separar los determinantes de la concentración y del tiempo hasta el estado estacionario.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2014-P113': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Velocidad de perfusión',
  clave:'Velocidad de perfusión igual a concentración deseada por aclaramiento: 10 mg/L por 0,5 L/h son 5 mg/h.',
  exp:'Es la aplicación directa de la fórmula del estado estacionario. Como la concentración de equilibrio es la velocidad de infusión dividida entre el aclaramiento, despejando queda que la *velocidad de infusión es igual a la concentración deseada multiplicada por el aclaramiento*. Aquí conviene cuidar las *unidades*, que es donde está la trampa: el aclaramiento viene dado en *500 mL/h*, es decir, *0,5 L/h*, y la concentración objetivo en *10 mg/L*. El producto es 10 mg/L por 0,5 L/h, y los litros se cancelan dejando *5 mg/h*. Lo interesante del resultado es lo que enseña sobre el aclaramiento: se puede leer como el volumen de plasma que el organismo depura por completo cada hora, de modo que para mantener una concentración estable basta con reponer exactamente lo que se elimina de ese volumen. Es el mismo razonamiento que sostiene las perfusiones de heparina, insulina o aminas vasoactivas.',
  no:{0:'50 mg/h saldría de usar el aclaramiento como si fuera 5 L/h: hay que convertir los 500 mL a litros.',1:'5 mL/h es un volumen, no una velocidad de administración de fármaco.',2:'100 mg/h no se obtiene de ninguna combinación correcta de estos datos.',3:'100 mg/mL es una concentración, no una velocidad de perfusión.'},
  trampa:'No convertir los 500 mL/h a 0,5 L/h multiplica el resultado por diez. Antes de operar, unificar unidades siempre.',
  dx:[],
  obj:'Calcular la velocidad de perfusión a partir del aclaramiento y la concentración objetivo.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2014-P111': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Cálculo de la dosis de mantenimiento',
  clave:'Dosis igual a concentración deseada por aclaramiento por intervalo: 10 por 1 por 12 son 120 mg cada 12 horas.',
  exp:'Cuando el fármaco se administra en *dosis múltiples* y no en perfusión continua, la lógica es la misma pero repartida en el tiempo. La velocidad de administración necesaria sigue siendo la *concentración media deseada multiplicada por el aclaramiento*, es decir, 10 mg/L por 1 L/h, lo que da *10 mg cada hora*. Como la dosis se va a dar cada *12 horas*, hay que aportar de golpe lo que el organismo eliminará en ese periodo: 10 mg/h por 12 h son *120 mg*. La fórmula general, con biodisponibilidad F, es dosis igual a concentración media por aclaramiento por intervalo, dividido entre F; aquí la biodisponibilidad es completa y por eso no modifica el cálculo. Dos matices prácticos que conviene ver: la fórmula da la concentración *media* del intervalo, no el pico ni el valle, de modo que si el fármaco tiene margen terapéutico estrecho hay que vigilar también esas oscilaciones; y para reducirlas, la solución no es cambiar la dosis total sino *acortar el intervalo* administrando cantidades menores más a menudo.',
  no:{1:'12 mg olvida multiplicar por el intervalo de dosificación.',2:'200 mg no se obtiene de ninguna combinación de estos datos.',3:'10 mg es la cantidad eliminada en una sola hora, no en las doce del intervalo.',4:'Sí es posible estimarla: bastan la concentración objetivo, el aclaramiento, el intervalo y la biodisponibilidad.'},
  trampa:'Se olvida multiplicar por el intervalo. La fórmula da miligramos por hora; para la dosis hay que cubrir todas las horas del intervalo.',
  dx:[],
  obj:'Calcular la dosis de mantenimiento en administración intermitente.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P119': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Extracción y aclaramiento hepático',
  clave:'Extracción igual a (entrada menos salida) entre entrada: (8-4)/8 es 0,5. Aclaramiento igual a flujo por extracción: 90 por 0,5 son 45 L/h.',
  exp:'El *coeficiente de extracción* mide qué fracción del fármaco que llega a un órgano es eliminada en un solo paso, y se calcula comparando lo que entra con lo que sale: la concentración arterial menos la venosa, dividido entre la arterial. Aquí entran 8 y salen 4, de modo que el hígado ha retirado la mitad de lo que le llegaba y la extracción es *0,5*. El *aclaramiento del órgano* es entonces el *flujo sanguíneo multiplicado por esa extracción*: 90 L/h por 0,5 dan *45 L/h*. Lo valioso es el concepto que hay detrás. Cuando la extracción es *alta*, próxima a 1, el hígado elimina casi todo lo que le llega y el aclaramiento queda limitado por *cuánta sangre pasa*, es decir, es *dependiente del flujo*: eso ocurre con el propranolol, la morfina, la lidocaína o el verapamilo, que además sufren un primer paso intenso. Cuando la extracción es *baja*, el aclaramiento depende de la *capacidad enzimática* y de la fracción libre, y ahí sí importan la inducción o inhibición del citocromo y la unión a proteínas.',
  no:{0:'4,0 sale de restar sin dividir: la extracción es una fracción y nunca puede superar 1.',2:'Una extracción de 1 significaría que no sale nada por la vena hepática, y salen 4.',3:'0,25 correspondería a una salida de 6, no de 4.',4:'Un valor de 2,0 es imposible: la extracción va siempre de 0 a 1.'},
  trampa:'Se olvida dividir entre la concentración de entrada. La extracción es una FRACCIÓN, así que un resultado mayor que 1 delata el error.',
  dx:[],
  obj:'Calcular el coeficiente de extracción y el aclaramiento de un órgano.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Rowland y Tozer, Farmacocinética Clínica.'
},
'MIR-2013-P121': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Fármacos con extracción hepática alta',
  clave:'Extracción hepática ALTA significa aclaramiento LIMITADO POR EL FLUJO: lo que importa es cuánta sangre llega al hígado.',
  exp:'La clave está en preguntarse qué es el *cuello de botella* de la eliminación. En un fármaco con *extracción alta*, el hígado es tan eficiente que elimina prácticamente todo lo que le llega en un solo paso; la maquinaria enzimática sobra, de modo que lo que limita el aclaramiento es *cuánta sangre le llega*, y por eso se dice que su aclaramiento es *dependiente del flujo*. Consecuencias clínicas concretas: en la insuficiencia cardiaca, la cirrosis con circulación colateral o el shock, el flujo hepático cae y estos fármacos se acumulan; y su biodisponibilidad oral es baja y muy variable por el primer paso. En cambio, y aunque el enunciado subraye la *elevada unión a proteínas*, esta *no influye* aquí: cuando la extracción es alta el hígado retira también el fármaco unido a la albúmina, porque lo desplaza a medida que lo aclara. La unión a proteínas sí es determinante en el caso contrario, el de los fármacos con extracción *baja*, en los que solo se elimina la fracción libre.',
  no:{1:'La unión a proteínas condiciona el aclaramiento de los fármacos de extracción BAJA, no de los de extracción alta.',2:'Solo influye el flujo: la unión a proteínas queda superada cuando la extracción es alta.',3:'Sí se ve influido, y mucho, por el flujo sanguíneo hepático.',4:'La biodisponibilidad es una consecuencia de la extracción alta, no el factor que determina el aclaramiento.'},
  trampa:'Se supone que a más unión a proteínas, menos eliminación. Con extracción alta el hígado arranca el fármaco de la albúmina y esa regla no aplica.',
  dx:[],
  obj:'Distinguir los fármacos con aclaramiento limitado por el flujo de los limitados por la capacidad enzimática.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Rowland y Tozer, Farmacocinética Clínica.'
},
'MIR-2014-P107': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Constante de eliminación',
  clave:'La constante de eliminación depende de la DISTRIBUCIÓN y la ELIMINACIÓN del fármaco, no de la dosis ni de la vía.',
  exp:'En una cinética *lineal* o de primer orden, la constante de eliminación es una propiedad *intrínseca* del fármaco en ese organismo, y se relaciona con los dos parámetros primarios de la farmacocinética mediante una fórmula que conviene tener grabada: la constante de eliminación es igual al *aclaramiento dividido entre el volumen de distribución*. De ahí que dependa de la *eliminación* —el aclaramiento, es decir, la capacidad de los órganos depuradores— y de la *distribución* —el volumen aparente en el que el fármaco se reparte—. Y de ahí también lo que *no* la modifica: ni la *dosis*, ni la *vía de administración*, ni la biodisponibilidad, ni la velocidad de absorción. Esa independencia es precisamente lo que define la linealidad, y explica que la *semivida* sea constante para un fármaco dado y que doblar la dosis doble las concentraciones sin cambiar el tiempo que tarda en eliminarse. Cuando esa regla se rompe —fenitoína, alcohol, salicilatos a dosis altas— se habla de cinética *saturable* o de orden cero, y ahí pequeños aumentos de dosis producen grandes saltos de concentración.',
  no:{0:'La vía de administración afecta a la absorción y a la biodisponibilidad, no a la constante de eliminación.',1:'Que la dosis no la modifique es precisamente lo que define una cinética lineal.',2:'Ese porcentaje es la biodisponibilidad, que condiciona cuánto llega, no a qué ritmo se elimina.',3:'La velocidad de llegada a la circulación es la absorción, un proceso independiente de la eliminación.'},
  trampa:'Se piensa que más dosis significa eliminación más rápida. En cinética lineal la constante no cambia: lo que cambia es la cantidad eliminada por unidad de tiempo.',
  dx:[],
  obj:'Relacionar la constante de eliminación con el aclaramiento y el volumen de distribución.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Rowland y Tozer, Farmacocinética Clínica.'
},
'MIR-2014-P118': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Monitorización de niveles plasmáticos',
  clave:'La muestra se extrae cuando ya se ha completado la DISTRIBUCIÓN: antes, el nivel plasmático no refleja el del tejido.',
  exp:'Monitorizar concentraciones tiene sentido solo en fármacos de *margen terapéutico estrecho* —digoxina, litio, aminoglucósidos, vancomicina, antiepilépticos, inmunosupresores— y con una condición técnica que la pregunta subraya: la muestra debe tomarse *una vez completada la fase de distribución*. Si se extrae antes, la concentración plasmática está artificialmente alta porque el fármaco todavía no ha llegado al tejido donde actúa, y se interpretará como toxicidad inexistente. El ejemplo canónico es la *digoxina*, cuya distribución tarda entre 6 y 8 horas, de modo que un nivel extraído a las dos horas de la dosis es engañoso. Además, lo habitual es medir en *valle*, justo antes de la dosis siguiente, y siempre tras alcanzar el *estado estacionario*, es decir, pasadas cuatro o cinco semividas. Los otros enunciados recogen errores conceptuales frecuentes: las reacciones *alérgicas* son idiosincrásicas y no dependen de la dosis, el nivel *nunca se interpreta solo* sino junto a la clínica y la función de los órganos depuradores, y la monitorización no depende de la vía sino del margen terapéutico.',
  no:{0:'Las reacciones alérgicas son idiosincrásicas y no guardan relación con la dosis administrada.',2:'El nivel plasmático nunca basta por sí solo: hay que interpretarlo junto con la clínica y la función renal y hepática.',3:'Existen otras técnicas válidas además del inmunoensayo, como la cromatografía.',4:'La monitorización depende del margen terapéutico del fármaco, no de la vía de administración.'},
  trampa:'Se extrae la muestra poco después de administrar el fármaco. En la digoxina eso da un nivel falsamente tóxico y lleva a retirar un tratamiento correcto.',
  dx:[],
  obj:'Conocer cuándo y por qué se extrae la muestra para monitorizar niveles plasmáticos.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P96': {
  esp:'Farmacología', tema:'Farmacocinética', sub:'Atrapamiento iónico',
  clave:'Ácido débil con pKa 3,5 en un estómago a pH 1,5: queda NO IONIZADO y por tanto se absorbe más del 90%.',
  exp:'El principio es el mismo que gobierna la absorción, la distribución y la eliminación renal de cualquier fármaco ionizable: solo la fracción *no ionizada* es liposoluble y puede atravesar membranas. Un *ácido débil* queda no ionizado cuando el medio es *más ácido que su pKa*. Aquí el ácido acetilsalicílico tiene pKa de *3,5* y el estómago en ayunas está a pH *1,5*, es decir, *dos unidades por debajo*; y cada unidad de diferencia multiplica por diez la proporción de la forma predominante, de modo que a dos unidades por debajo del pKa la relación entre forma no ionizada e ionizada es de *100 a 1*, o sea, más del *99%* está no ionizado y disponible para absorberse. La respuesta correcta es por tanto más del 90%. Dos matices que merecen quedarse: en la práctica la mayor parte de la absorción de la aspirina ocurre igualmente en el *intestino delgado*, por su enorme superficie, pese a que allí el pH sea desfavorable; y esta misma lógica es la que justifica *alcalinizar la orina* en la intoxicación por salicilatos, para ionizarlos, atraparlos en el túbulo y eliminarlos.',
  no:{0:'Menos del 10% correspondería a una situación en la que el fármaco estuviera mayoritariamente ionizado.',1:'Ese rango tampoco encaja: con dos unidades de pH por debajo del pKa la fracción no ionizada supera el 99%.',3:'Entre el 20 y el 40% supondría un pH próximo al pKa, no dos unidades por debajo.',4:'El 50% se daría exactamente cuando el pH iguala al pKa, es decir, a pH 3,5.'},
  trampa:'Se invierte la regla. Un ácido se mantiene entero en medio ácido; una base, en medio alcalino. Y solo lo no ionizado atraviesa la membrana.',
  dx:[],
  obj:'Aplicar la relación entre pH, pKa e ionización a la absorción de un fármaco.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},

/* ==================== FARMACOLOGÍA CLÍNICA ==================== */
'MIR-2013-P100': {
  esp:'Farmacología', tema:'Antiagregantes', sub:'Clopidogrel',
  clave:'El clopidogrel bloquea el receptor P2Y12, y al bloquearlo DESINHIBE la adenilciclasa: el AMPc SUBE. El enunciado se contradice a sí mismo.',
  exp:'La afirmación falsa lo es por partida doble y merece desmontarse despacio, porque enseña el mecanismo entero. El *ADP* actúa sobre el receptor plaquetario *P2Y12*, que está acoplado a una proteína *Gi*; al activarse, *inhibe la adenilciclasa* y hace *bajar* el AMPc, lo que favorece la activación de la glicoproteína IIb/IIIa y la agregación. El *clopidogrel* bloquea ese receptor, de modo que hace justo lo contrario: *libera* a la adenilciclasa de su inhibición y el AMPc *sube*, con lo que la plaqueta no se agrega. Así que el enunciado es falso porque atribuye al fármaco la acción del ADP y, además, se contradice: inhibir la adenilciclasa haría *descender* el AMPc, no incrementarlo. El resto de afirmaciones son ciertas: pertenece a las *tienopiridinas* junto a ticlopidina y prasugrel; tiene *mucha menos mielotoxicidad* que la ticlopidina, que producía neutropenia y púrpura trombótica trombocitopénica; su efecto es *irreversible* sobre la plaqueta y dura toda su vida media, de siete a diez días; y por eso se suspende con antelación antes de cirugía mayor.',
  no:{0:'Es cierto: el clopidogrel pertenece al grupo de las tienopiridinas.',2:'Es cierto: su mielotoxicidad es mucho menor que la de la ticlopidina.',3:'Es cierto: su acción es irreversible sobre la plaqueta y por eso más prolongada.',4:'Es cierto: al ser irreversible, hay que suspenderlo con antelación ante cirugía con riesgo hemorrágico.'},
  trampa:'Se acepta la frase sin leerla entera. Inhibir la adenilciclasa BAJA el AMPc: la propia opción se desmiente a sí misma.',
  dx:[],
  obj:'Explicar el mecanismo del clopidogrel sobre el receptor P2Y12 y el AMPc plaquetario.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P103': {
  esp:'Farmacología', tema:'Psicofármacos', sub:'Mirtazapina',
  clave:'La sedación de la mirtazapina es por bloqueo de receptores HISTAMINÉRGICOS H1, igual que la de los antihistamínicos clásicos.',
  exp:'La mirtazapina es un antidepresivo *noradrenérgico y serotoninérgico específico*, y su perfil de efectos se deduce por completo de los receptores que bloquea. El bloqueo de los *autorreceptores alfa-2* presinápticos es lo que aumenta la liberación de noradrenalina y serotonina y sostiene su efecto antidepresivo. El bloqueo de los receptores *5-HT2* y *5-HT3* explica que, a diferencia de los ISRS, produzca *poca disfunción sexual y pocas náuseas*, e incluso que se use como antiemético. Y el bloqueo potente de los receptores *histaminérgicos H1* explica sus dos efectos adversos más característicos: la *sedación y la somnolencia*, y el *aumento del apetito con ganancia de peso*. Eso no es solo un inconveniente: es la razón por la que la mirtazapina se elige a propósito en el paciente *deprimido con insomnio y pérdida de peso*, sobre todo en el anciano, administrándola por la noche. Y explica también la curiosidad de que sede *más* a dosis bajas, porque al subir la dosis predomina el efecto noradrenérgico.',
  no:{0:'Los receptores 5-HT1 se relacionan con el efecto de los triptanes y de la buspirona, no con la sedación de la mirtazapina.',1:'El bloqueo alfa-2 sostiene su efecto antidepresivo, no la somnolencia.',3:'La mirtazapina no actúa sobre receptores GABA: ese es el mecanismo de benzodiacepinas y barbitúricos.',4:'El bloqueo muscarínico produce sequedad de boca, estreñimiento y retención urinaria, no somnolencia como efecto principal.'},
  trampa:'Se atribuye la sedación al efecto serotoninérgico. En psicofarmacología, cuando algo da sueño y hambre, casi siempre hay un bloqueo H1 detrás.',
  dx:[],
  obj:'Relacionar el perfil de receptores de la mirtazapina con sus efectos clínicos.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Stahl, Psicofarmacología Esencial.'
},
'MIR-2013-P102': {
  esp:'Farmacología', tema:'Cardiovascular', sub:'Digital y diuréticos',
  clave:'La HIPOPOTASEMIA potencia la toxicidad digitálica: por eso preocupa el diurético que hace perder potasio.',
  exp:'El concepto que la pregunta quiere transmitir es sólido y muy preguntable: la *digoxina* y el *potasio* compiten por el mismo sitio de unión en la *bomba sodio-potasio ATPasa*. Cuando el potasio baja, la digoxina se une con más facilidad, de modo que la *hipopotasemia potencia su toxicidad* y puede desencadenar arritmias graves con niveles de digoxina aparentemente normales. Como los *diuréticos del asa* y las *tiazidas* provocan pérdida renal de potasio, en un paciente digitalizado son precisamente los que exigen vigilancia, y de ahí que la respuesta oficial señale al *ahorrador de potasio*, que evita esa pérdida y además, en el caso de la espironolactona y la eplerenona, mejora la supervivencia en la insuficiencia cardiaca. Ahora bien, conviene decirlo con precisión: la palabra *necesariamente* del enunciado no refleja la práctica actual. En la insuficiencia cardiaca congestiva el diurético que descongestiona es el *de asa*, y lo que se hace es usarlo vigilando el potasio y suplementándolo o asociando un ahorrador, no renunciar a él. La idea que hay que llevarse es la interacción, no la prohibición.',
  no:{0:'El diurético de asa es el que realmente descongestiona; el problema es que hace perder potasio y obliga a vigilarlo.',1:'La tiazida también produce hipopotasemia y es menos eficaz en la congestión aguda.',2:'Los diuréticos osmóticos como el manitol no se usan en la insuficiencia cardiaca: pueden aumentar el volumen intravascular y empeorarla.',4:'Los inhibidores de la anhidrasa carbónica son diuréticos débiles y producen acidosis metabólica.'},
  trampa:'Quedarse con "en el digitalizado se usa ahorrador de potasio" como regla absoluta. Lo que hay que recordar es que la hipopotasemia dispara la toxicidad digitálica.',
  dx:[],
  obj:'Explicar la interacción entre hipopotasemia y toxicidad digitálica.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman y guías ESC de insuficiencia cardiaca.'
},

/* ==================== ANTIMICROBIANOS ==================== */
'MIR-2013-P110': {
  esp:'Farmacología', tema:'Antimicrobianos', sub:'Cefalosporinas de tercera generación',
  clave:'Frente a ENTEROBACTER hay que evitar las cefalosporinas de tercera generación: inducen su betalactamasa AmpC y aparece resistencia durante el tratamiento.',
  exp:'*Enterobacter*, y con él Serratia, Citrobacter freundii, Providencia y Morganella —el grupo que se recuerda con las siglas *SPICE*—, posee una betalactamasa cromosómica de tipo *AmpC* que normalmente está reprimida. El problema es que las cefalosporinas de tercera generación la *inducen*: el tratamiento empieza funcionando y, al cabo de unos días, emergen mutantes desreprimidos que producen la enzima de forma constitutiva y el paciente *recae con una cepa ya resistente*, incluso aunque el antibiograma inicial informara sensibilidad. Por eso en infecciones graves por estos gérmenes se prefieren *cefepima*, que es más estable frente a AmpC, o directamente un *carbapenémico*. El resto de opciones son incorrectas y repasan el grupo: el representante de la tercera generación es la *ceftriaxona* o la cefotaxima, mientras que la *cefepima* es de cuarta; sí son de elección en la meningitis *neumocócica*, asociadas a vancomicina; *nunca* cubren *Listeria*, que es intrínsecamente resistente a todas las cefalosporinas y exige ampicilina; y su asociación con un *aminoglucósido* es habitual y a menudo sinérgica.',
  no:{0:'La cefepima es de CUARTA generación; el representante de la tercera es la ceftriaxona o la cefotaxima.',2:'Sí son útiles en la meningitis neumocócica: son precisamente el eje del tratamiento, con vancomicina asociada.',3:'Listeria es intrínsecamente resistente a TODAS las cefalosporinas: se trata con ampicilina.',4:'La asociación con aminoglucósidos es frecuente y busca sinergia en infecciones graves.'},
  trampa:'Se confía en el antibiograma inicial. Con Enterobacter la sensibilidad de partida no garantiza nada: la resistencia se induce durante el tratamiento.',
  dx:[],
  obj:'Conocer el fenómeno de inducción de AmpC en el grupo SPICE.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Mandell, Enfermedades Infecciosas.'
},
'MIR-2013-P89': {
  esp:'Farmacología', tema:'Antimicrobianos', sub:'Penicilinas antipseudomónicas',
  clave:'La única penicilina de la lista con actividad frente a Pseudomonas es la piperacilina-tazobactam.',
  exp:'Las penicilinas se ordenan en grupos con espectros muy distintos, y conviene tenerlos separados porque de ahí salen la mitad de las preguntas de antibióticos. Las *penicilinas naturales* —penicilina G y V— cubren estreptococos, meningococo, Treponema y anaerobios de boca. Las *isoxazolilpenicilinas* como la *cloxacilina* son antiestafilocócicas y su papel es *Staphylococcus aureus* sensible a meticilina. Las *aminopenicilinas* —ampicilina y amoxicilina— añaden cobertura frente a enterococo, Listeria y algunos gramnegativos, y con clavulánico ganan los productores de betalactamasa. Y las *ureidopenicilinas y carboxipenicilinas*, cuyo representante actual es la *piperacilina*, son las únicas con actividad *antipseudomónica*, potenciada con *tazobactam* como inhibidor de betalactamasas. Conviene fijar la lista completa de betalactámicos activos frente a Pseudomonas: piperacilina-tazobactam, *ceftazidima* y *cefepima*, *meropenem* e *imipenem* —pero no ertapenem— y el *aztreonam*.',
  no:{0:'La amoxicilina-clavulánico amplía el espectro a productores de betalactamasa, pero no cubre Pseudomonas.',1:'La cloxacilina es antiestafilocócica y carece de actividad frente a gramnegativos.',2:'La penicilina V es de espectro reducido, fundamentalmente frente a estreptococos.',4:'La ampicilina cubre enterococo y Listeria, pero no Pseudomonas.'},
  trampa:'Se elige la amoxicilina-clavulánico por ser la de mayor espectro entre las conocidas. Amplio espectro no equivale a antipseudomónico.',
  dx:[],
  obj:'Identificar la penicilina con actividad antipseudomónica dentro de los grupos de penicilinas.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Mandell, Enfermedades Infecciosas.'
},
'MIR-2014-P16': {
  esp:'Farmacología', tema:'Antimicrobianos', sub:'Ceftazidima',
  clave:'La ceftazidima es la cefalosporina ANTIPSEUDOMÓNICA: ese es su nicho, y a cambio cubre mal al neumococo y al estafilococo.',
  exp:'Dentro de las cefalosporinas de tercera generación hay una división que conviene tener clara porque cambia el uso clínico. La *ceftriaxona* y la *cefotaxima* tienen excelente actividad frente a *neumococo, meningococo y Haemophilus*, y por eso son el eje del tratamiento de la neumonía y de la meningitis, pero *no cubren Pseudomonas*. La *ceftazidima* hace justo lo contrario: es la cefalosporina de tercera generación *antipseudomónica*, y ese es su nicho —infecciones nosocomiales, neutropenia febril, fibrosis quística—, pero a cambio tiene actividad *pobre frente a neumococo y estafilococo*, de modo que sería una mala elección en una neumonía comunitaria. La *cefepima*, de cuarta generación, combina ambas cosas: cubre Pseudomonas *y* mantiene buena actividad frente a grampositivos, además de ser más estable frente a AmpC. Y hay que descartar de plano los gérmenes que ninguna cefalosporina cubre: *SARM*, que exige vancomicina, daptomicina o linezolid; los *atípicos* como Mycoplasma y Chlamydia, sin pared celular y por tanto insensibles a los betalactámicos; y las *micobacterias*.',
  no:{0:'Mycoplasma carece de pared celular: ningún betalactámico es activo frente a él.',2:'Ninguna cefalosporina convencional cubre SARM; solo lo hacen las de quinta generación, ceftarolina y ceftobiprol.',3:'Chlamydia es un patógeno intracelular sin pared típica: se trata con doxiciclina o azitromicina.',4:'La tuberculosis exige tuberculostáticos específicos, no betalactámicos.'},
  trampa:'Se asume que toda cefalosporina de tercera generación es intercambiable. Ceftriaxona y ceftazidima cubren cosas distintas y casi opuestas.',
  dx:[],
  obj:'Situar la ceftazidima dentro del espectro de las cefalosporinas.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Mandell, Enfermedades Infecciosas.'
},
'MIR-2014-P116': {
  esp:'Farmacología', tema:'Antimicrobianos', sub:'Aminoglucósidos',
  clave:'Los aminoglucósidos tienen una fase de distribución RÁPIDA, no lenta. Lo lento es su segunda fase de eliminación desde el tejido renal.',
  exp:'Los aminoglucósidos son moléculas *muy polares y muy hidrosolubles*, y de esa única propiedad se deduce toda su farmacocinética. Al ser polares *no se absorben por vía digestiva*, lo que permite usarlos por vía oral para descontaminar el intestino sin efecto sistémico —aunque en la insuficiencia renal grave o con la mucosa dañada puede absorberse lo suficiente para dar toxicidad, como recoge otra de las opciones—. Su volumen de distribución es *pequeño*, próximo al del líquido extracelular, no penetran bien en el sistema nervioso central ni en las secreciones bronquiales, y se distribuyen *deprisa*, no lentamente: ahí está el error del enunciado que se pide señalar. *No se metabolizan* y se eliminan íntegros por *filtración glomerular*, de modo que su dosis debe ajustarse a la función renal. Y sí existe una *segunda fase de eliminación muy lenta*, que corresponde al fármaco acumulado en la corteza renal y en la endolinfa del oído interno: eso es lo que explica su *nefrotoxicidad y ototoxicidad*, y por qué la administración en *dosis única diaria* las reduce sin perder eficacia, ya que su acción es concentración-dependiente.',
  no:{0:'Es correcto: por ser moléculas muy polares no se absorben en el tubo digestivo.',1:'Es correcto: en la insuficiencia renal grave puede absorberse lo suficiente para producir toxicidad.',3:'Es correcto: no se metabolizan y se eliminan inalterados por filtración glomerular.',4:'Es correcto: la segunda fase lenta corresponde al fármaco depositado en corteza renal y oído interno.'},
  trampa:'Se confunde la fase de distribución con la segunda fase de eliminación. La distribución es rápida; lo lento es soltar el fármaco acumulado en el tejido.',
  dx:[],
  obj:'Deducir la farmacocinética de los aminoglucósidos a partir de su polaridad.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P83': {
  esp:'Farmacología', tema:'Interacciones', sub:'Linezolid y síndrome serotoninérgico',
  clave:'El LINEZOLID es un inhibidor reversible de la MAO: con ISRS puede desencadenar un síndrome serotoninérgico.',
  exp:'Es una de las interacciones más importantes y peor conocidas de la práctica hospitalaria. El *linezolid*, una oxazolidinona que se usa frente a grampositivos resistentes —SARM, enterococo resistente a vancomicina—, tiene además una propiedad inesperada para un antibiótico: es un *inhibidor reversible y no selectivo de la monoaminooxidasa*. Al combinarse con fármacos que aumentan la serotonina —*ISRS*, venlafaxina, duloxetina, tramadol, triptanes, IMAO— puede precipitar un *síndrome serotoninérgico*, cuya tríada es *alteración del estado mental* con agitación, *hiperactividad autonómica* con fiebre, taquicardia, sudoración y midriasis, e *hiperactividad neuromuscular* con temblor, hiperreflexia y *clonus*, especialmente en miembros inferiores, que es el signo más discriminativo. Ese origen mixto obliga a revisar la medicación psiquiátrica antes de prescribirlo y a vigilar estrechamente si no puede evitarse. Por el mismo motivo se recomienda precaución con alimentos ricos en tiramina, aunque al ser inhibición reversible el riesgo hipertensivo es mucho menor que con los IMAO clásicos. Conviene recordar también su otra toxicidad: *mielosupresión* con trombopenia en tratamientos de más de dos semanas.',
  no:{0:'La neomicina es un aminoglucósido de uso tópico y para descontaminación intestinal, sin actividad sobre la MAO.',1:'La teicoplanina es un glucopéptido emparentado con la vancomicina, sin interacción serotoninérgica.',3:'La clindamicina es una lincosamida; su problema característico es la colitis por Clostridioides difficile.',4:'El meropenem es un carbapenémico; su interacción reseñable es que reduce los niveles de valproato.'},
  trampa:'No se piensa en un antibiótico como causa de síndrome serotoninérgico. El linezolid es la excepción y por eso se pregunta.',
  dx:['Síndrome serotoninérgico','Síndrome neuroléptico maligno','Sepsis'],
  obj:'Reconocer el linezolid como inhibidor de la MAO y su riesgo de síndrome serotoninérgico.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman y guías IDSA.'
},
'MIR-2013-P27': {
  esp:'Medicina Interna', tema:'Infectología', sub:'Tratamiento de la enfermedad de Chagas',
  clave:'La enfermedad de Chagas se trata con BENZNIDAZOL, y como alternativa nifurtimox.',
  exp:'El tratamiento antiparasitario del *Trypanosoma cruzi* solo dispone de dos fármacos, y el de primera línea es el *benznidazol*, un nitroimidazol; la alternativa es el *nifurtimox*. Su eficacia depende críticamente del *momento* en que se administren: son muy eficaces en la *fase aguda*, en el *Chagas congénito* y en niños y adultos jóvenes con infección crónica *reciente*, situaciones en las que consiguen curación parasitológica en un porcentaje alto; en cambio, en la fase *crónica avanzada* con miocardiopatía o megavísceras establecidas su beneficio es limitado, porque el daño de órgano ya está hecho y es en buena medida irreversible. También se indican ante *reactivación* en inmunodeprimidos y antes de un trasplante. Ambos tienen mala tolerancia: el benznidazol produce con frecuencia *exantema*, neuropatía periférica y leucopenia, y obliga a tratamientos de dos meses. Es un tema con peso propio en el ENURM por la epidemiología de la región, y conviene tenerlo separado del tratamiento *sintomático* de sus complicaciones, que es el de la insuficiencia cardiaca, las arritmias y el megacolon.',
  no:{0:'La anfotericina B es un antifúngico y se usa además en la leishmaniasis visceral, no en el Chagas.',1:'El cotrimoxazol se emplea en Pneumocystis, nocardiosis y toxoplasmosis.',2:'La ivermectina trata la estrongiloidiasis, la oncocercosis y la escabiosis.',3:'El albendazol es un antihelmíntico de amplio espectro, sin actividad frente a tripanosomas.'},
  trampa:'Se elige un antiparasitario genérico. Cada protozoo tiene su fármaco, y para el Chagas solo existen dos: benznidazol y nifurtimox.',
  dx:['Enfermedad de Chagas','Leishmaniasis','Toxoplasmosis'],
  obj:'Conocer el tratamiento antiparasitario del Chagas y cuándo es eficaz.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Mandell, Enfermedades Infecciosas, y documentos de la OPS.'
},
'MIR-2013-P87': {
  esp:'Medicina Interna', tema:'Infectología', sub:'Paludismo grave',
  clave:'Paludismo grave por P. falciparum: derivados de la ARTEMISININA, hoy artesunato intravenoso.',
  exp:'El tratamiento del paludismo se decide cruzando *especie*, *gravedad* y *resistencias*. En el *paludismo grave por Plasmodium falciparum* —definido por alteración de conciencia, convulsiones, insuficiencia renal, distrés, acidosis, hipoglucemia, anemia grave o parasitemia elevada— el tratamiento de elección es el *artesunato intravenoso*, un derivado de la *artemisinina*, que demostró en los ensayos SEAQUAMAT y AQUAMAT una reducción de mortalidad clara frente a la quinina, además de mejor tolerancia. Los derivados de la artemisinina actúan muy deprisa sobre las formas asexuadas y por eso reducen la parasitemia con rapidez, aunque tienen semivida corta y deben completarse con un segundo fármaco, motivo por el cual en el paludismo *no complicado* se usan siempre en *combinación* —las terapias combinadas basadas en artemisinina—. Los distractores permiten repasar: la *cloroquina* solo sirve donde no hay resistencia y en las especies no falciparum; la *quinina* es la alternativa clásica cuando no hay artesunato; la *primaquina* actúa sobre los *hipnozoítos* hepáticos de P. vivax y P. ovale para evitar recaídas, y requiere descartar déficit de G6PD; y el *estibogluconato* es un antimonial para la leishmaniasis.',
  no:{0:'El estibogluconato sódico es un antimonial pentavalente para la leishmaniasis, no un antipalúdico.',1:'La primaquina erradica los hipnozoítos hepáticos de vivax y ovale: no trata el paludismo grave por falciparum.',2:'La cloroquina es ineficaz frente a las cepas resistentes de falciparum, que son la mayoría.',4:'La quinina es la alternativa histórica, hoy desplazada por el artesunato, que reduce más la mortalidad.'},
  trampa:'Se responde cloroquina por ser el antipalúdico más conocido. En falciparum grave y multirresistente es justamente el fármaco que no sirve.',
  dx:['Paludismo grave por P. falciparum','Paludismo no complicado','Fiebre tifoidea'],
  obj:'Elegir el tratamiento del paludismo grave según especie y resistencias.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con las guías de la OMS sobre malaria.'
},
'MIR-2013-P230': {
  esp:'Farmacología', tema:'Digestivo', sub:'Inhibidores de la bomba de protones',
  clave:'Los IBP tardan 3-5 días en alcanzar su máxima inhibición ácida: son más potentes que los anti-H2, pero más lentos en arrancar.',
  exp:'Los inhibidores de la bomba de protones son *profármacos* que necesitan acumularse en el canalículo ácido de la célula parietal, activarse allí y unirse de forma *irreversible* a la bomba H+/K+ ATPasa. De esa mecánica se derivan sus dos rasgos. El primero es que su efecto es *acumulativo*: como solo inhiben las bombas activas en ese momento y las bombas se renuevan, hacen falta *tres a cinco días* de tomas repetidas para alcanzar la inhibición máxima, y por eso su inicio de acción es *más lento* que el de los antagonistas H2, que actúan desde la primera dosis. El segundo es que, una vez alcanzada la meseta, su potencia antisecretora es *muy superior* a la de los anti-H2 y no desarrolla la *taquifilaxia* que estos sí presentan. De ahí también dos consejos prácticos: se administran *en ayunas, unos 30 minutos antes del desayuno*, porque necesitan que las bombas estén activándose; y en la erradicación de *Helicobacter pylori* nunca van solos, sino formando parte de una combinación con dos o tres antibióticos.',
  no:{1:'Son claramente MÁS eficaces que los antagonistas H2 en potencia antisecretora.',2:'En monoterapia no erradican el Helicobacter: forman parte de combinaciones con antibióticos.',3:'Su inicio de acción es más LENTO que el de los anti-H2, no más rápido.',4:'Sí son útiles en la profilaxis y el tratamiento de las úlceras de estrés.'},
  trampa:'Se supone que más potente significa más rápido. Con los IBP ocurre lo contrario: tardan días en desplegar todo su efecto.',
  dx:[],
  obj:'Explicar el inicio de acción acumulativo de los inhibidores de la bomba de protones.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2014-P10': {
  esp:'Farmacología', tema:'Digestivo', sub:'Sulfasalazina',
  clave:'La sulfasalazina es un profármaco que las BACTERIAS DEL COLON activan rompiendo su enlace azo: por eso actúa solo en el colon.',
  exp:'La sulfasalazina está formada por *sulfapiridina* y *ácido 5-aminosalicílico* unidos por un *enlace azo*. Ese enlace es la clave del diseño: resiste la digestión en el estómago y el intestino delgado, de modo que el fármaco llega intacto al *colon*, donde la *azorreductasa de la flora bacteriana* lo rompe mediante una *reducción* y libera los dos componentes. El *5-ASA* es la molécula activa y actúa *tópicamente* sobre la mucosa colónica, apenas se absorbe y ahí ejerce su efecto antiinflamatorio; la *sulfapiridina* se absorbe y es la responsable de la mayoría de los *efectos adversos* —náuseas, cefalea, exantema, oligospermia reversible, anemia hemolítica en el déficit de G6PD y reacciones de hipersensibilidad—. Precisamente por eso se desarrollaron las mesalazinas modernas, que aportan 5-ASA sin la sulfapiridina y se toleran mucho mejor. Este mecanismo de liberación dependiente de la flora es un buen ejemplo de cómo un profármaco puede usarse para *dirigir* un fármaco a un órgano concreto. Hay que suplementar *ácido fólico*, porque la sulfasalazina interfiere con su absorción.',
  no:{0:'No hay ningún éster en la molécula: la unión entre ambos componentes es un enlace azo.',1:'Tampoco es una amida: si lo fuera, se hidrolizaría antes de llegar al colon.',2:'La desalquilación oxidativa es una reacción de fase I hepática, no el mecanismo de activación aquí.',4:'La hidroxilación aromática es otra reacción hepática de fase I, ajena a este profármaco.'},
  trampa:'Se olvida que la activación depende de la flora. Eso explica que actúe en el colon y que su efecto disminuya si se altera la microbiota.',
  dx:[],
  obj:'Explicar la activación colónica de la sulfasalazina y el origen de sus efectos adversos.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P5': {
  esp:'Farmacología', tema:'Oncología', sub:'Mesna y ciclofosfamida',
  clave:'El mesna neutraliza la ACROLEÍNA, el metabolito de la ciclofosfamida que produce cistitis hemorrágica.',
  exp:'La *ciclofosfamida* es un profármaco que el hígado activa mediante el citocromo P450, y en ese proceso genera, además del agente alquilante que destruye el tumor, un metabolito tóxico llamado *acroleína*. La acroleína no tiene actividad antitumoral y se concentra en la *orina*, donde irrita el urotelio y produce la complicación característica del fármaco: la *cistitis hemorrágica*, que puede llegar a ser grave y que a largo plazo aumenta el riesgo de carcinoma vesical. El *mesna* es un compuesto con un grupo *tiol* libre que se elimina también por la orina y allí se une a la acroleína, *inactivándola* antes de que dañe la vejiga. Es esencial entender dos cosas: el mesna actúa *solo en la vía urinaria*, de modo que *no reduce* la eficacia antitumoral de la ciclofosfamida ni protege de su mielotoxicidad; y la protección se completa con *hidratación abundante* y micción frecuente. El mismo esquema se aplica a la *ifosfamida*, que produce todavía más acroleína y con la que el mesna es obligado.',
  no:{0:'No forman ningún complejo con el ADN: el mesna ni siquiera llega a interactuar con el material genético.',2:'El mesna no es un alquilante: es un tiol protector sin actividad antitumoral.',3:'El mesna actúa como reductor y captador, no como oxidante, y no incrementa la citotoxicidad.',4:'No inhibe el citocromo P450; si lo hiciera, impediría la activación del propio citostático.'},
  trampa:'Se piensa que el mesna resta eficacia al tratamiento. Actúa solo en la orina, así que protege la vejiga sin tocar el efecto antitumoral.',
  dx:[],
  obj:'Explicar la profilaxis de la cistitis hemorrágica por ciclofosfamida.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P155': {
  esp:'Farmacología', tema:'Oncología', sub:'Leucemia mieloide crónica',
  clave:'Leucemia mieloide crónica: IMATINIB, inhibidor de la tirosina cinasa BCR-ABL.',
  exp:'La leucemia mieloide crónica se define por una alteración genética concreta: la traslocación *t(9;22)*, el *cromosoma Filadelfia*, que fusiona los genes *BCR* y *ABL* generando una *tirosina cinasa constitutivamente activa* que dirige la proliferación mieloide. El *imatinib* fue el primer fármaco diseñado contra una diana molecular concreta y bloquea justamente esa cinasa, transformando por completo el pronóstico: de una enfermedad que evolucionaba inevitablemente a crisis blástica y cuya única opción curativa era el trasplante, se pasó a supervivencias que se aproximan a las de la población general, con tratamiento oral. Es el ejemplo canónico de *terapia dirigida* y por eso se pregunta tanto. Los distractores repasan lo que quedó desplazado: el *interferón* y el *busulfán* o la *hidroxiurea* eran el tratamiento previo y hoy son históricos o meramente citorreductores iniciales; y el *rituximab* es un anti-CD20 que actúa sobre linfocitos *B*, ajeno por completo a una leucemia de estirpe *mieloide*. En caso de resistencia o intolerancia existen inhibidores de segunda y tercera generación como dasatinib, nilotinib o ponatinib.',
  no:{0:'El interferón fue el tratamiento previo al imatinib y hoy tiene un papel muy marginal.',1:'La hidroxiurea solo citorreduce de forma transitoria: no actúa sobre la causa molecular.',3:'El rituximab es un anti-CD20 que actúa sobre linfocitos B, no sobre la línea mieloide.',4:'El busulfán es un alquilante clásico, hoy relegado a la preparación para trasplante.'},
  trampa:'Se elige un citostático clásico. En la leucemia mieloide crónica el tratamiento no es citotóxico sino dirigido contra la proteína de fusión.',
  dx:['Leucemia mieloide crónica','Reacción leucemoide','Mielofibrosis'],
  obj:'Relacionar el cromosoma Filadelfia con el mecanismo del imatinib.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con guías ESMO de leucemia mieloide crónica.'
},
'MIR-2013-P81': {
  esp:'Farmacología', tema:'Inmunomoduladores', sub:'Rituximab',
  clave:'El anti-CD20 es el RITUXIMAB. La terminación -ximab indica anticuerpo quimérico.',
  exp:'El *rituximab* es un anticuerpo monoclonal dirigido contra el antígeno *CD20*, presente en la superficie de los linfocitos *B* maduros pero no en las células madre ni en las células plasmáticas, lo que permite depleccionar la población B sin comprometer la inmunidad de forma permanente. Sus indicaciones cruzan la hematología y la reumatología: *linfomas B* y *leucemia linfática crónica*, *artritis reumatoide* refractaria a anti-TNF, *vasculitis ANCA*, *púrpura trombocitopénica inmune* y anemias hemolíticas autoinmunes. Conviene aprovechar la pregunta para fijar la *nomenclatura* de los monoclonales, que permite deducir mucho de un nombre: la terminación *-momab* indica origen murino, *-ximab* quimérico —como rituximab, infliximab o cetuximab—, *-zumab* humanizado —trastuzumab, bevacizumab, tocilizumab— y *-umab* completamente humano —adalimumab, denosumab—. Cuanto más humanizado, menor inmunogenicidad. Como efectos adversos hay que vigilar las *reacciones infusionales* y, sobre todo, la *reactivación del virus de la hepatitis B*, que obliga a cribarla antes de tratar.',
  no:{0:'El alemtuzumab es un anti-CD52, usado en leucemia linfática crónica y en esclerosis múltiple.',1:'El muromonab es un anti-CD3 murino, empleado históricamente en el rechazo de trasplante.',2:'El abalizumab no corresponde a un anti-CD20 de uso establecido en artritis reumatoide.',4:'El visilizumab es un anti-CD3 humanizado, ajeno a la diana CD20.'},
  trampa:'Se memoriza el nombre sin la diana. Conviene asociar siempre monoclonal con antígeno: rituximab con CD20, trastuzumab con HER2, tocilizumab con IL-6.',
  dx:[],
  obj:'Identificar el rituximab como anti-CD20 y descifrar la nomenclatura de los monoclonales.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},

'MIR-2013-P88': {
  esp:'Farmacología', tema:'Inmunomoduladores', sub:'Monoclonales en oncohematología',
  clave:'En la leucemia linfática crónica el monoclonal es el RITUXIMAB: sus células son linfocitos B y expresan CD20.',
  exp:'La pregunta se resuelve emparejando *diana* y *tejido*. La *leucemia linfática crónica* es una proliferación de linfocitos *B* maduros, que expresan *CD20*, de modo que el anticuerpo indicado es el *rituximab*, habitualmente combinado con quimioterapia en los esquemas clásicos R-FC o R-bendamustina, aunque hoy compite con los inhibidores de BTK como el ibrutinib y con el venetoclax. Los demás monoclonales de la lista permiten repasar sus dianas, que conviene tener asociadas de memoria porque se preguntan una y otra vez: el *trastuzumab* actúa contra *HER2* en el cáncer de mama y gástrico; el *bevacizumab* contra el *VEGF*, bloqueando la angiogénesis en tumores de colon, pulmón y otros, y también en la degeneración macular; el *cetuximab* contra el *receptor del factor de crecimiento epidérmico*, útil en el cáncer colorrectal solo si el gen *RAS* no está mutado; y el *denosumab* contra el *ligando de RANK*, empleado en osteoporosis y en metástasis óseas. Ninguno de ellos tiene relación con el linfocito B.',
  no:{0:'El trastuzumab actúa contra HER2 en cáncer de mama y gástrico.',1:'El bevacizumab bloquea el VEGF y la angiogénesis; no tiene diana linfoide.',2:'El denosumab actúa sobre el ligando de RANK: es un fármaco del hueso.',3:'El cetuximab actúa sobre el receptor del factor de crecimiento epidérmico, en tumores sólidos con RAS nativo.'},
  trampa:'Se memoriza la indicación sin la diana. Si se recuerda que la leucemia linfática crónica es de células B, el CD20 lleva solo al rituximab.',
  dx:[],
  obj:'Emparejar cada anticuerpo monoclonal con su diana molecular.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con guías ESMO y Goodman y Gilman.'
},
'MIR-2013-P86': {
  esp:'Farmacología', tema:'Metabolismo óseo', sub:'Denosumab',
  clave:'El denosumab es un anticuerpo contra el LIGANDO DE RANK: bloquea la maduración del osteoclasto.',
  exp:'El remodelado óseo está gobernado por un trío que conviene tener claro. El *osteoblasto* produce *RANKL*, el ligando de RANK, que al unirse al receptor *RANK* del precursor osteoclástico lo hace madurar y *reabsorber hueso*; y produce también *osteoprotegerina*, un receptor señuelo que capta RANKL y frena esa reabsorción. El *denosumab* es un anticuerpo monoclonal completamente humano que imita a la osteoprotegerina: se une al *RANKL* y evita que active a su receptor, con lo que la formación y la supervivencia de los osteoclastos caen y la resorción se desploma. Se administra por vía *subcutánea cada seis meses*, no requiere ajuste renal —lo que lo hace útil cuando los bifosfonatos están contraindicados por filtrado bajo— y tiene una particularidad importante: su efecto es *reversible* y al suspenderlo se produce un *rebote* con pérdida rápida de masa ósea y riesgo de fracturas vertebrales múltiples, de modo que nunca debe interrumpirse sin pasar a otro antirresortivo. Los demás fármacos tienen mecanismos distintos: los *bifosfonatos* se fijan a la hidroxiapatita e inhiben la farnesil pirofosfato sintasa del osteoclasto, el *raloxifeno* es un modulador selectivo del receptor estrogénico y la *teriparatida* es análogo de PTH y el único claramente *anabólico*.',
  no:{0:'El alendronato es un bifosfonato: se fija al hueso e inhibe la farnesil pirofosfato sintasa del osteoclasto.',2:'La calcitonina inhibe directamente al osteoclasto por su propio receptor, no por la vía RANK.',3:'El raloxifeno es un modulador selectivo del receptor de estrógenos.',4:'La teriparatida es análogo de PTH y actúa como anabólico óseo, no como antirresortivo.'},
  trampa:'Se agrupan todos los antirresortivos como si tuvieran el mismo mecanismo. Solo el denosumab actúa sobre la vía RANK-RANKL.',
  dx:[],
  obj:'Explicar el mecanismo del denosumab dentro del sistema RANK-RANKL-osteoprotegerina.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con guías de la Endocrine Society sobre osteoporosis.'
},
'MIR-2013-P85': {
  esp:'Farmacología', tema:'Hormonas sexuales', sub:'Efectos adversos de los estrógenos',
  clave:'Los estrógenos aumentan el riesgo de cáncer de ENDOMETRIO y de mama, no de ovario. Sobre el ovario incluso hay efecto protector con anticoncepción.',
  exp:'Los efectos adversos de los estrógenos se deducen de sus acciones fisiológicas. Producen *retención hidrosalina*, y de ahí el *edema* y el aumento de peso; *náuseas* y *cefalea*, sobre todo al inicio; *tensión y dolor mamario* por estímulo del tejido glandular; y, lo más relevante, *riesgo trombótico* aumentado por el incremento de factores de coagulación, especialmente por vía oral. En el terreno oncológico, el estímulo proliferativo se ejerce sobre dos tejidos: el *endometrio*, donde el estrógeno sin oposición gestagénica produce hiperplasia y *adenocarcinoma* —motivo por el cual en la mujer con útero siempre se asocia un gestágeno—, y la *mama*, con un aumento moderado del riesgo en tratamientos prolongados. El *ovario* es la excepción que la pregunta busca: no solo no figura entre los tumores claramente inducidos, sino que la anticoncepción hormonal combinada tiene un efecto *protector* bien documentado sobre el cáncer de ovario y de endometrio, por la supresión de la ovulación mantenida.',
  no:{0:'El edema por retención hidrosalina es un efecto adverso característico.',1:'La mastalgia y la tensión mamaria son efectos frecuentes del estímulo glandular.',3:'Las náuseas son muy comunes, sobre todo al iniciar el tratamiento.',4:'La cefalea es frecuente y puede agravar una migraña previa, sobre todo con aura.'},
  trampa:'Se asume que los estrógenos aumentan el riesgo de todos los tumores ginecológicos. Sobre el ovario la anticoncepción combinada es protectora.',
  dx:[],
  obj:'Conocer los efectos adversos de los estrógenos y su relación con cada tumor ginecológico.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman y documentos de la IARC.'
},
'MIR-2013-P95': {
  esp:'Farmacología', tema:'Hematología', sub:'Ferroterapia oral',
  clave:'Por vía oral solo sirven las sales FERROSAS (Fe2+): son las que se absorben. Las férricas (Fe3+) hay que reducirlas antes.',
  exp:'El hierro solo se absorbe en el duodeno y el yeyuno proximal en su forma *ferrosa*, Fe2+, a través del transportador DMT1. El hierro *férrico*, Fe3+, debe ser *reducido* previamente por una ferrirreductasa de la membrana intestinal, un paso que limita mucho su absorción, y por eso las sales orales que se emplean son *ferrosas*: sulfato, gluconato o fumarato ferroso, siendo el sulfato el más usado y barato. De ahí salen los consejos prácticos: se toma *en ayunas* porque los alimentos reducen su absorción, aunque a menudo haya que darlo con comida para tolerarlo; la *vitamina C* la mejora al mantener el hierro reducido; y la empeoran los *inhibidores de la bomba de protones*, los antiácidos, el calcio, el té y el café. La duración también importa: no bastan quince días, hay que mantenerlo entre *tres y seis meses después de normalizar la hemoglobina* para rellenar los depósitos, controlando la ferritina. Y la vía *parenteral*, reservada a la intolerancia, la malabsorción, las pérdidas continuas o la enfermedad renal crónica, usa precisamente complejos *férricos* —hierro sacarosa, carboximaltosa férrica—, porque en la sangre el hierro se transporta como Fe3+.',
  no:{1:'Las sales férricas se absorben mal por vía oral: necesitan reducirse previamente a ferroso.',2:'El hierro-dextrano es una formulación PARENTERAL, no oral.',3:'Quince días son insuficientes: hay que prolongarlo meses para reponer los depósitos.',4:'Por vía parenteral se emplean complejos férricos, no sales ferrosas.'},
  trampa:'Se confunden ferroso y férrico. Regla: para tragar, ferroso; para inyectar, férrico.',
  dx:[],
  obj:'Elegir la forma química adecuada de hierro según la vía de administración.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},
'MIR-2013-P156': {
  esp:'Medicina Interna', tema:'Hematología', sub:'Perfil férrico',
  clave:'Transferrina ALTA con saturación BAJA: ferropenia. El organismo fabrica más transportador porque falta carga.',
  exp:'El perfil férrico se interpreta como un sistema de transporte con tres datos que hay que leer juntos. La *transferrina* —o su equivalente, la capacidad total de fijación del hierro— es el *camión* que transporta el hierro; el *hierro sérico* es la *carga*; y el *índice de saturación* es qué proporción de camiones va llena. En la *ferropenia* el organismo responde a la falta de hierro *fabricando más transferrina* para captar hasta la última molécula disponible, de modo que la transferrina *sube* mientras la saturación *cae*, típicamente por debajo del 15-16%; la ferritina, que refleja los depósitos, está *baja*, y ese es el parámetro más específico. Conviene contrastarlo con la *anemia de trastorno crónico*, en la que la hepcidina secuestra el hierro en los macrófagos: allí bajan tanto el hierro como la transferrina y la ferritina está normal o alta. Las otras opciones no cursan con este patrón: la anemia *perniciosa* es macrocítica por déficit de B12, y la *drepanocitosis*, la *talasemia* y la *esferocitosis* son hemolíticas, con hierro normal o elevado por la propia destrucción de hematíes.',
  no:{0:'La anemia perniciosa es macrocítica por déficit de B12, con perfil férrico normal.',1:'La drepanocitosis es hemolítica: no cursa con transferrina alta ni saturación baja.',2:'En la talasemia mayor hay sobrecarga de hierro por hemólisis y transfusiones, con saturación ALTA.',3:'La esferocitosis es hemolítica, con hierro normal o elevado.'},
  trampa:'Se piensa que si falta hierro debe bajar todo. La transferrina hace lo contrario: sube, porque el cuerpo fabrica más transportador.',
  dx:['Anemia ferropénica','Anemia de trastorno crónico','Talasemia'],
  obj:'Interpretar el perfil férrico y diferenciar ferropenia de anemia de trastorno crónico.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Harrison, 21.ª ed.'
},
'MIR-2013-P99': {
  esp:'Farmacología', tema:'Analgesia', sub:'Estreñimiento inducido por opioides',
  clave:'La METILNALTREXONA bloquea los receptores opioides del intestino sin atravesar la barrera hematoencefálica: quita el estreñimiento sin quitar la analgesia.',
  exp:'El estreñimiento es el efecto adverso más constante de los opioides y, a diferencia de las náuseas o la somnolencia, *no desarrolla tolerancia*: persiste durante todo el tratamiento, de modo que en el paciente oncológico debe prevenirse desde el primer día. Su causa es la activación de los receptores *mu* del plexo mientérico, que enlentece el tránsito y aumenta la absorción de agua. La *metilnaltrexona* resuelve el problema con elegancia: es un antagonista opioide al que se ha añadido un grupo *metilo cuaternario* que lo hace permanentemente *cargado* y, por tanto, incapaz de atravesar la *barrera hematoencefálica*. El resultado es que bloquea los receptores *periféricos* del intestino, revirtiendo el estreñimiento, sin tocar los *centrales*, con lo que la analgesia se mantiene intacta y no precipita un síndrome de abstinencia. Se administra por vía subcutánea y su efecto suele producirse en horas. En la práctica, el primer escalón siguen siendo los laxantes osmóticos y estimulantes pautados de forma profiláctica, y la metilnaltrexona se reserva para cuando estos fracasan.',
  no:{0:'La metilcelulosa es un laxante formador de masa: requiere buena ingesta de líquidos y es poco eficaz aquí.',1:'La glicerina en supositorio tiene efecto local y puntual, insuficiente para un estreñimiento mantenido.',2:'La loperamida es un ANTIDIARREICO opioide periférico: agravaría el estreñimiento.',4:'El racecadotrilo es también antidiarreico, un inhibidor de la encefalinasa.'},
  trampa:'Se elige la loperamida por reconocerla como fármaco intestinal relacionado con opioides. Es lo contrario de lo que hace falta.',
  dx:[],
  obj:'Explicar el fundamento de los antagonistas opioides de acción periférica.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con guías SECPAL y Goodman y Gilman.'
},
'MIR-2014-P101': {
  esp:'Farmacología', tema:'Neurología', sub:'Profilaxis de la migraña',
  clave:'La FLUNARIZINA es profilaxis de la migraña. El sumatriptán y la dihidroergotamina tratan la crisis, no la previenen.',
  exp:'En la migraña hay que separar dos tratamientos que se confunden constantemente. El *sintomático* corta la crisis ya establecida: AINE y paracetamol en las leves, y *triptanes* como el sumatriptán —agonistas 5-HT1B/1D— o los *ergóticos* como la dihidroergotamina en las moderadas o graves. El *preventivo* se indica cuando hay *tres o más crisis al mes*, cuando son muy incapacitantes o cuando el paciente abusa de la medicación sintomática, y se toma a diario durante meses para reducir la frecuencia. Sus fármacos son otros: *betabloqueantes* como el propranolol, que son la primera línea; *antiepilépticos* como el topiramato y el valproato; *antidepresivos tricíclicos* como la amitriptilina, especialmente si hay cefalea tensional asociada o insomnio; el calcioantagonista *flunarizina*, que es la respuesta y resulta especialmente útil en niños y en la migraña con aura, vigilando la sedación, el aumento de peso y el parkinsonismo en el anciano; y hoy también los *anticuerpos anti-CGRP*. Nunca hay que usar un triptán a diario como prevención: produce *cefalea por abuso de medicación*.',
  no:{0:'La dihidroergotamina es un ergótico para el tratamiento de la crisis aguda.',1:'La meperidina es un opioide: no tiene papel en la profilaxis y favorece el abuso de medicación.',3:'La clorpromazina es un antipsicótico que puede usarse como rescate antiemético en la crisis, no como preventivo.',4:'El sumatriptán es el prototipo de tratamiento sintomático de la crisis.'},
  trampa:'Se confunde abortar la crisis con prevenirla. Un triptán tomado a diario no previene: genera cefalea por abuso de medicación.',
  dx:['Migraña','Cefalea tensional','Cefalea por abuso de medicación'],
  obj:'Separar el tratamiento sintomático del preventivo en la migraña.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con guías de la Sociedad Española de Neurología.'
},
'MIR-2014-P103': {
  esp:'Farmacología', tema:'Neumología', sub:'Tratamiento del asma',
  clave:'A demanda solo va el agonista beta-2 de acción CORTA. Todo lo demás es tratamiento de mantenimiento pautado.',
  exp:'El tratamiento del asma se organiza en dos categorías que no deben mezclarse. Los *aliviadores* o de rescate se usan *a demanda*, cuando aparecen los síntomas, y su representante es el *agonista beta-2 de acción corta* inhalado, salbutamol o terbutalina, que broncodilata en minutos. Los *controladores* se toman *a diario y de forma pautada* para reducir la inflamación bronquial de fondo: *corticoides inhalados*, que son la base del tratamiento, agonistas beta-2 de *acción larga* —que nunca se usan solos por el riesgo de mortalidad, sino siempre asociados al corticoide—, antileucotrienos y anticolinérgicos de acción prolongada. Conviene añadir un matiz actual: las guías GINA han desplazado el uso del beta-2 de acción corta *aislado* como rescate, y hoy recomiendan como aliviador preferente la combinación de *formoterol con budesonida*, precisamente porque el rescate con broncodilatador solo enmascara la inflamación y se asocia a peores resultados. Un dato clínico útil: si el paciente necesita el rescate más de dos veces por semana, su asma está mal controlada y hay que subir el escalón de mantenimiento.',
  no:{0:'Los glucocorticoides inhalados son el pilar del tratamiento de MANTENIMIENTO, no de rescate.',1:'El beta-2 de acción larga tarda en actuar y nunca debe usarse solo: siempre asociado a corticoide inhalado.',3:'Los anticolinérgicos inhalados de acción prolongada son tratamiento de mantenimiento en escalones altos.',4:'El cromoglicato es un estabilizador de mastocitos de uso preventivo y hoy prácticamente en desuso.'},
  trampa:'Se piensa en el corticoide inhalado como rescate por ser el más potente. No broncodilata: su efecto tarda días y es antiinflamatorio.',
  dx:['Asma bronquial'],
  obj:'Distinguir el tratamiento de rescate del de mantenimiento en el asma.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con la estrategia GINA.'
},
'MIR-2014-P158': {
  esp:'Medicina Interna', tema:'Nefrología', sub:'Microalbuminuria',
  clave:'La microalbuminuria es el marcador PRECOZ de nefropatía diabética, y además predice riesgo cardiovascular.',
  exp:'La *microalbuminuria*, hoy llamada albuminuria moderadamente aumentada, se define como un cociente *albúmina/creatinina en orina entre 30 y 300 mg/g* en al menos dos de tres muestras separadas en el tiempo. Su valor es doble. Por un lado es el *primer signo detectable* de nefropatía diabética, que aparece años antes de que la creatinina se altere y cuando la lesión todavía es *reversible o frenable*, motivo por el cual debe buscarse *anualmente* en todo diabético tipo 2 desde el diagnóstico y en el tipo 1 a partir de los cinco años de evolución. Por otro, es un potente *marcador de riesgo cardiovascular* incluso en no diabéticos, porque refleja una disfunción endotelial generalizada. Detectarla obliga a actuar: bloqueo del sistema renina-angiotensina con IECA o ARA-II, control estricto de la glucemia y de la tensión arterial, y hoy también inhibidores de SGLT2. Conviene precisar lo que no es: no es *proteinuria nefrótica*, que exige más de 3,5 gramos al día, ni indica enfermedad terminal, y hay que confirmarla descartando causas transitorias como el ejercicio intenso, la fiebre, la infección urinaria o la descompensación glucémica.',
  no:{0:'La enfermedad renal terminal se define por el filtrado glomerular, no por la microalbuminuria.',1:'El síndrome nefrótico exige proteinuria superior a 3,5 g al día, muy por encima de este rango.',3:'La glomerulonefritis suele cursar con hematuria dismórfica y proteinuria mayor.',4:'La proteinuria ortostática es un hallazgo benigno del joven que desaparece con el decúbito.'},
  trampa:'Se minimiza por llamarse "micro". Es el aviso más precoz y el momento en que el tratamiento todavía cambia la historia natural.',
  dx:['Nefropatía diabética incipiente','Proteinuria ortostática','Glomerulonefritis'],
  obj:'Interpretar la microalbuminuria como marcador renal y cardiovascular precoz.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con guías KDIGO y estándares de la ADA.'
},
'MIR-2014-P160': {
  esp:'Medicina Interna', tema:'Reumatología', sub:'Cristales en la gota',
  clave:'En la gota el líquido sinovial contiene cristales de URATO MONOSÓDICO: en aguja y con birrefringencia intensamente NEGATIVA.',
  exp:'El diagnóstico de certeza de la gota es la identificación de *cristales de urato monosódico* en el líquido sinovial mediante microscopio de luz *polarizada*, y sus dos rasgos hay que memorizarlos como pareja: forma de *aguja* y birrefringencia *intensamente negativa*, lo que significa que el cristal se ve *amarillo* cuando su eje es *paralelo* al del compensador. El contraste obligado es la *condrocalcinosis* o pseudogota, causada por *pirofosfato cálcico*: cristales *romboidales* y birrefringencia *débilmente positiva*, azules en paralelo. El líquido de la gota es además *inflamatorio*, con recuentos que pueden superar las 50.000 células de predominio neutrófilo, cifra que se solapa con la de una artritis séptica; de ahí la regla que no admite excepciones: *siempre se cultiva*, porque la presencia de cristales no descarta una infección y ambas pueden coexistir. Los demás cristales de la lista corresponden a otras situaciones: el *oxalato cálcico* aparece en la insuficiencia renal en diálisis, y el fosfato amónico magnésico —fosfato triple o estruvita— es un cristal *urinario* propio de la infección por gérmenes ureasa positivos.',
  no:{0:'Los cristales de ácido hipúrico no son un hallazgo articular relevante.',1:'Los cristales de tirosina aparecen en trastornos metabólicos del aminoácido, no en el líquido sinovial.',2:'El fosfato triple o estruvita es un cristal URINARIO, propio de la infección por gérmenes ureasa positivos.',4:'El oxalato cálcico se ve en la oxalosis y en pacientes en diálisis, no en la gota.'},
  trampa:'Se confunde la birrefringencia de la gota con la de la pseudogota. Regla: aguja y negativa intensa para el urato; romboide y positiva débil para el pirofosfato.',
  dx:['Gota','Artritis por pirofosfato','Artritis séptica'],
  obj:'Identificar los cristales de urato y diferenciarlos de los de pirofosfato.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con guías EULAR sobre gota.'
},
'MIR-2014-P180': {
  esp:'Farmacología', tema:'Toxicología', sub:'Antídoto del paracetamol',
  clave:'Sobredosis de paracetamol: N-ACETILCISTEÍNA, que repone el glutatión consumido por el metabolito tóxico.',
  exp:'El paracetamol se metaboliza mayoritariamente por *glucuronoconjugación y sulfatación*, vías seguras que se *saturan* cuando la dosis es alta. Entonces cobra protagonismo una vía menor, la del *citocromo CYP2E1*, que genera un metabolito muy reactivo, el *NAPQI*. En condiciones normales el NAPQI es neutralizado por el *glutatión* hepático, pero en la sobredosis los depósitos se agotan y el metabolito se une covalentemente a las proteínas del hepatocito, provocando *necrosis centrolobulillar*. La *N-acetilcisteína* actúa precisamente ahí: aporta *cisteína*, el aminoácido limitante de la síntesis de glutatión, repone los depósitos y permite seguir inactivando el NAPQI; además tiene efectos antioxidantes y hemodinámicos beneficiosos incluso cuando el daño ya está establecido. Su eficacia es máxima en las *primeras 8 a 10 horas*, aunque se administra igualmente más tarde. Conviene tener presentes los factores que agravan la intoxicación por inducir el CYP2E1 o vaciar el glutatión: *alcoholismo crónico*, ayuno, desnutrición y algunos antiepilépticos.',
  no:{0:'El flumazenilo antagoniza las benzodiacepinas.',1:'El edetato sódico cálcico es un quelante para la intoxicación por plomo.',2:'La pralidoxima reactiva la colinesterasa en la intoxicación por organofosforados.',4:'El nitrito de amilo forma parte del tratamiento clásico de la intoxicación por cianuro.'},
  trampa:'Se administra el antídoto solo si hay alteración hepática. A las pocas horas la analítica es normal por definición: la decisión se toma con los niveles.',
  dx:['Intoxicación por paracetamol'],
  obj:'Explicar el mecanismo de la hepatotoxicidad del paracetamol y el papel de la N-acetilcisteína.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Goldfrank, Toxicologic Emergencies.'
},
'MIR-2013-P183': {
  esp:'Farmacología', tema:'Toxicología', sub:'Antídoto de los opiáceos',
  clave:'La NALOXONA es el antagonista de los receptores opioides: revierte la depresión respiratoria en minutos.',
  exp:'La *naloxona* es un antagonista *competitivo* de los receptores opioides, con afinidad máxima por el receptor *mu*, y su indicación es la intoxicación aguda por *opiáceos*, cuya tríada clásica es *depresión respiratoria*, *miosis puntiforme* y *disminución del nivel de conciencia*. La depresión respiratoria es lo que mata, y es también el objetivo del tratamiento: la dosis se titula buscando *recuperar una ventilación adecuada*, no despertar por completo al paciente, porque una reversión brusca en un consumidor crónico precipita un *síndrome de abstinencia* agudo con agitación, vómitos y riesgo de aspiración. Hay un detalle que conviene no olvidar: la *semivida de la naloxona es corta*, de 30 a 90 minutos, mucho menor que la de la mayoría de los opiáceos y desde luego que la de la metadona, de modo que el paciente puede *volver a deprimirse* cuando el antídoto se agota; por eso hay que vigilarlo varias horas y a menudo repetir dosis o usar perfusión. Conviene fijar el resto de parejas antídoto-tóxico que aparecen en las opciones: flumazenilo para benzodiacepinas, bicarbonato para tricíclicos y anticuerpos Fab para digital.',
  no:{1:'El antagonista de las benzodiacepinas es el flumazenilo, no la naloxona.',2:'Los barbitúricos carecen de antídoto específico: el tratamiento es de soporte y alcalinización de la orina.',3:'La intoxicación por tricíclicos se trata con bicarbonato sódico para el ensanchamiento del QRS.',4:'La intoxicación digitálica se revierte con anticuerpos antidigoxina Fab.'},
  trampa:'Se da una dosis alta de golpe para despertar al paciente. El objetivo es la respiración; despertar bruscamente provoca abstinencia y agitación.',
  dx:['Intoxicación por opiáceos','Intoxicación por benzodiacepinas','Ictus de tronco'],
  obj:'Conocer la indicación y las limitaciones de la naloxona.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goldfrank, Toxicologic Emergencies.'
},

'MIR-2013-P181': {
  esp:'Farmacología', tema:'Toxicología', sub:'Anticuerpos antidigoxina',
  clave:'Los fragmentos Fab antidigoxina son el antídoto de la intoxicación DIGITÁLICA grave.',
  exp:'Los *fragmentos Fab* son la porción de un anticuerpo que reconoce el antígeno, obtenida al digerir la inmunoglobulina y separarla de la porción Fc; al ser más pequeños, difunden mejor a los tejidos y son mucho menos inmunogénicos. Los *Fab antidigoxina* se unen con enorme afinidad a la molécula de digoxina, la retiran de su sitio de acción en la bomba sodio-potasio ATPasa y el complejo se elimina por vía renal. Sus indicaciones son las de la intoxicación *grave*: arritmias ventriculares potencialmente letales, bradiarritmias o bloqueos que no responden a atropina, e *hiperpotasemia* superior a 5 mEq/L en la intoxicación aguda, que es un marcador de mal pronóstico porque refleja el bloqueo masivo de la bomba. Un detalle importante: tras administrarlos, la digoxinemia medida por los métodos habituales se dispara y deja de ser interpretable, porque el laboratorio detecta también la fracción unida al anticuerpo. Y hay que recordar el manejo previo: suspender el fármaco, corregir la hipopotasemia si la hay, y evitar el calcio intravenoso en la hiperpotasemia digitálica.',
  no:{1:'Los barbitúricos no tienen antídoto específico: se tratan con soporte y alcalinización urinaria.',2:'Las anfetaminas se manejan con sedación con benzodiacepinas y medidas de soporte.',3:'Los salicilatos se tratan con alcalinización de la orina y, en casos graves, hemodiálisis.',4:'Los antihistamínicos, con toxíndrome anticolinérgico, pueden requerir fisostigmina en casos seleccionados.'},
  trampa:'Se olvida que la hiperpotasemia es criterio de gravedad. En la intoxicación digitálica aguda, un potasio alto indica antídoto, no solo tratamiento del potasio.',
  dx:['Intoxicación digitálica'],
  obj:'Conocer las indicaciones de los fragmentos Fab antidigoxina.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goldfrank, Toxicologic Emergencies.'
},
'MIR-2013-P184': {
  esp:'Farmacología', tema:'Toxicología', sub:'Intoxicación por paraquat',
  clave:'El paraquat se acumula en el PULMÓN y produce fibrosis progresiva. Y el oxígeno la EMPEORA.',
  exp:'El *paraquat* es un herbicida bipiridilo de altísima letalidad y su toxicidad tiene una diana muy concreta. Los *neumocitos tipo I y II* lo captan activamente mediante el sistema de transporte de poliaminas, de modo que se concentra selectivamente en el *pulmón* alcanzando concentraciones muy superiores a las plasmáticas. Allí sufre un ciclo redox continuo que genera *radicales libres de oxígeno*, provoca peroxidación lipídica y destruye la membrana alveolocapilar: primero un edema y una hemorragia alveolar, y después, en quienes sobreviven a la fase aguda, una *fibrosis pulmonar progresiva e irreversible* que causa la muerte en días o semanas. De ahí sale la particularidad terapéutica más contraintuitiva y más preguntada: la *oxigenoterapia está contraindicada* salvo hipoxemia crítica, porque el oxígeno alimenta el ciclo redox y *acelera* el daño; se administra solo lo imprescindible y a veces se busca deliberadamente mantener saturaciones bajas. No existe antídoto: el manejo es descontaminación digestiva precoz con tierra de Fuller o carbón activado, y soporte.',
  no:{1:'Puede haber alteraciones hematológicas, pero no son la manifestación principal ni la causa de muerte.',2:'La neurotoxicidad no es el rasgo dominante; el paraquat se relaciona epidemiológicamente con el parkinsonismo, pero no es su toxicidad aguda.',3:'La toxicidad ocular se limita a las salpicaduras, con úlcera corneal, y no es la afectación sistémica principal.',4:'La ototoxicidad no forma parte del cuadro del paraquat.'},
  trampa:'Se administra oxígeno por reflejo ante la insuficiencia respiratoria. En el paraquat el oxígeno es combustible para la lesión.',
  dx:['Intoxicación por paraquat','Distrés respiratorio agudo','Neumonitis química'],
  obj:'Reconocer la toxicidad pulmonar del paraquat y por qué el oxígeno la agrava.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goldfrank, Toxicologic Emergencies.'
},
'MIR-2013-P187': {
  esp:'Farmacología', tema:'Toxicología', sub:'Dosis letal 50',
  clave:'La sustancia más tóxica es la de DL50 más BAJA: la toxina botulínica, el veneno más potente que se conoce.',
  exp:'La *dosis letal 50* es la dosis, expresada por kilo de peso, que mata al 50% de los animales de experimentación, y es la forma estándar de comparar la toxicidad *aguda* de distintas sustancias. Su lectura es *inversa*: cuanto *menor* es la DL50, *más tóxica* es la sustancia, porque hace falta menos cantidad para matar. Con ese criterio, la *toxina botulínica* de Clostridium botulinum es la sustancia más tóxica conocida, con una DL50 del orden de *nanogramos por kilo*, muy por debajo de la estricnina, la nicotina, el curare o la morfina, que se mueven en el rango de miligramos. La razón de esa potencia es enzimática: la toxina escinde las proteínas *SNARE* de la terminal presináptica colinérgica e impide de forma irreversible la liberación de acetilcolina, de modo que unas pocas moléculas bloquean permanentemente una unión neuromuscular y producen una *parálisis flácida descendente* con afectación de pares craneales y fallo respiratorio. Y esa misma potencia, aplicada localmente y a dosis ínfimas, es lo que la convierte en un fármaco útil en distonías, espasticidad y espasmo hemifacial.',
  no:{0:'La estricnina es muy tóxica y produce convulsiones por bloqueo de la glicina, pero su DL50 es de miligramos por kilo.',1:'La nicotina es tóxica en dosis de decenas de miligramos, muy lejos de los nanogramos de la toxina.',2:'La morfina tiene una DL50 mucho más alta y además dispone de antídoto.',4:'El curare bloquea la placa motora pero requiere dosis en el rango de miligramos.'},
  trampa:'Se lee la DL50 al derecho. Es una escala inversa: el número más pequeño señala al veneno más potente.',
  dx:[],
  obj:'Interpretar la DL50 como medida inversa de toxicidad.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Casarett y Doull, Toxicología.'
},
'MIR-2014-P181': {
  esp:'Farmacología', tema:'Toxicología', sub:'Análisis toxicológico del pelo',
  clave:'El pelo guarda un registro RETROSPECTIVO: permite documentar exposiciones de meses atrás que ya no están en sangre ni en orina.',
  exp:'Las tres matrices toxicológicas cubren *ventanas temporales* distintas y esa es la idea que hay que llevarse. La *sangre* refleja lo que ocurre *ahora*, en las últimas horas, y es la que se correlaciona con la clínica. La *orina* amplía la ventana a *días*, y es la matriz habitual del cribado de drogas. Y el *pelo* abre una ventana de *meses*: las sustancias se incorporan desde el torrente sanguíneo a la matriz del folículo y quedan *fijadas* en la queratina a medida que el pelo crece, de modo que, como este crece a un ritmo aproximado de un centímetro al mes, el análisis segmentado del tallo permite reconstruir *cuándo* hubo exposición y estimar si fue puntual o mantenida. Sus aplicaciones son sobre todo forenses y de control: consumo crónico de drogas, exposición a *metales pesados* como el arsenio, el plomo o el talio, sumisión química y control de abstinencia. Sus limitaciones son la *contaminación externa* del tallo y la variabilidad según el color y el tratamiento cosmético del cabello.',
  no:{1:'El cambio de color del pelo no es un método diagnóstico de intoxicación; las líneas de Mees, por ejemplo, aparecen en las uñas.',2:'El pelo no constituye ninguna barrera eficaz frente a los corrosivos.',3:'El consumo de anfetaminas no interrumpe el crecimiento del pelo.',4:'El pelo tiene un interés toxicológico enorme, sobre todo en toxicología forense y laboral.'},
  trampa:'Se descarta el pelo por parecer una matriz menor. Es la única que documenta lo que ocurrió hace meses.',
  dx:[],
  obj:'Conocer la ventana temporal de cada matriz toxicológica.',
  ref:'Examen FIR 2014, Ministerio de Sanidad de España. Contrastado con Casarett y Doull, Toxicología.'
},
'MIR-2013-P1': {
  esp:'Farmacología', tema:'Toxicología', sub:'Bioactivación de las aflatoxinas',
  clave:'La aflatoxina se transforma en un EPÓXIDO que se une covalentemente a la guanina del ADN: por eso es hepatotóxica y cancerígena.',
  exp:'La *aflatoxina B1*, producida por hongos del género *Aspergillus* que contaminan cereales, maíz y frutos secos mal conservados, es un ejemplo perfecto de *bioactivación metabólica*: la molécula que se ingiere no es tóxica por sí misma, y es el propio hígado el que la convierte en veneno. El *citocromo P450* la oxida en una reacción de *fase I* generando un *epóxido* muy reactivo, el 8,9-epóxido, que forma un *enlace covalente con el nitrógeno 7 de la guanina* del ADN. Ese aducto produce mutaciones características, en particular en el gen supresor *p53*, y de ahí su potente acción *cancerígena*: la aflatoxina es uno de los principales factores de riesgo de *hepatocarcinoma* en África subsahariana y en el sudeste asiático, y su efecto se *multiplica* cuando coexiste con infección crónica por virus de la hepatitis B. Conviene retener el concepto general, que se repite con el paracetamol, la ciclofosfamida o el benceno: la toxicidad de muchos xenobióticos no procede de la molécula original sino de un metabolito reactivo generado en la fase I, y la defensa habitual es la conjugación con *glutatión* de la fase II.',
  no:{0:'La liberación de aminas aromáticas es el mecanismo de otros carcinógenos, no el de la aflatoxina.',1:'El catión nitrenio corresponde a la bioactivación de las aminas aromáticas, y además la fase II suele DESTOXIFICAR, no activar.',3:'La bioactivación reductora es el mecanismo del nitrofurantoína o del paraquat, no de la aflatoxina.',4:'El mecanismo radicalario con especies reactivas de oxígeno corresponde a tóxicos como el paraquat.'},
  trampa:'Se supone que la fase II siempre destoxifica y la fase I siempre inactiva. Aquí ocurre lo contrario: la fase I fabrica el metabolito que produce el cáncer.',
  dx:['Hepatocarcinoma','Hepatotoxicidad tóxica'],
  obj:'Explicar la bioactivación de la aflatoxina y su relación con el hepatocarcinoma.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Casarett y Doull, Toxicología, y documentos de la IARC.'
},
'MIR-2013-P12': {
  esp:'Farmacología', tema:'Antimicrobianos', sub:'Inhibidores de la proteasa del VIH',
  clave:'Los inhibidores de la proteasa imitan el ESTADO DE TRANSICIÓN de la reacción: por eso se unen mucho mejor que el sustrato real.',
  exp:'La *proteasa del VIH* es una enzima que corta las poliproteínas víricas Gag y Gag-Pol para generar las proteínas estructurales y enzimáticas maduras; sin ese corte, los viriones que salen de la célula son *inmaduros y no infectivos*. Los inhibidores como el *indinavir*, el ritonavir o el darunavir se diseñaron mediante *diseño racional* a partir de la estructura del sitio activo, imitando el *estado de transición* de la reacción de hidrólisis del enlace peptídico. La razón por la que eso funciona es elegante: una enzima no está diseñada para unir con fuerza a su sustrato ni a su producto, sino que su sitio activo tiene *máxima afinidad por el estado de transición*, que es lo que le permite catalizar; una molécula estable que se parezca a ese estado se une, por tanto, con una afinidad muy superior a la del sustrato natural, y bloquea la enzima de forma competitiva y potente. En la práctica hay que recordar dos cosas de esta familia: se potencian con *ritonavir o cobicistat*, inhibidores del CYP3A4, y tienen *muchas interacciones* y toxicidad metabólica con dislipemia y lipodistrofia.',
  no:{0:'No es un profármaco: el indinavir es activo tal cual se administra.',1:'No alquila ni se une de forma irreversible: su inhibición es competitiva y reversible.',3:'El inhibidor suicida se transforma por la propia enzima en un producto que la inactiva; no es el caso.',4:'La simetría de la molécula no es lo que explica su afinidad, sino la imitación del estado de transición.'},
  trampa:'Se supone que un buen inhibidor debe parecerse al sustrato. Se une mucho mejor si se parece al estado de transición.',
  dx:[],
  obj:'Explicar el fundamento de los inhibidores del estado de transición.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Goodman y Gilman, Bases Farmacológicas de la Terapéutica.'
},

/* ==================== CIENCIAS BÁSICAS ==================== */
'MIR-2013-P128': {
  esp:'Ciencias Básicas', tema:'Bioquímica', sub:'Ciclo de la urea',
  clave:'El FUMARATO es la bisagra: sale del ciclo de la urea al romperse el argininosuccinato y entra en el ciclo de Krebs.',
  exp:'El *ciclo de la urea* y el *ciclo del ácido cítrico* comparten un metabolito que los conecta, y conviene ver dónde exactamente. En el ciclo de la urea, la *argininosuccinato liasa* rompe el argininosuccinato y produce dos moléculas: *arginina*, que continúa en el ciclo para dar urea y ornitina, y *fumarato*, que sale y entra en el *ciclo de Krebs*. Allí el fumarato se hidrata a *malato* y este se oxida a *oxalacetato*, que puede transaminarse a *aspartato* y volver al ciclo de la urea, cerrando lo que se conoce como la *lanzadera aspartato-argininosuccinato*. Esa conexión no es un detalle académico: explica que los dos nitrógenos de la urea tengan orígenes distintos —uno procede del amoníaco libre a través del carbamoil fosfato y el otro del *aspartato*— y que el ciclo de la urea esté energéticamente acoplado al metabolismo intermediario. Clínicamente importa porque los *defectos del ciclo de la urea* producen *hiperamoniemia* con encefalopatía, y porque en la insuficiencia hepática la incapacidad de convertir amoníaco en urea es el motor de la encefalopatía hepática.',
  no:{0:'El ácido úrico procede del catabolismo de las purinas, no del ciclo de la urea.',1:'El succinato pertenece al ciclo de Krebs pero no es el punto de conexión con el ciclo de la urea.',2:'El amoníaco entra en el ciclo de la urea, pero no es un intermediario del ciclo de Krebs.',3:'La urea es el producto final que se excreta: no participa en el ciclo del ácido cítrico.'},
  trampa:'Se responde amoníaco por ser el sustrato más recordado del ciclo. El nexo entre ambos ciclos es el fumarato que sale de la argininosuccinato liasa.',
  dx:[],
  obj:'Localizar el punto de conexión entre el ciclo de la urea y el ciclo de Krebs.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Lehninger, Principios de Bioquímica.'
},
'MIR-2013-P135': {
  esp:'Ciencias Básicas', tema:'Fisiología', sub:'Efecto Bohr',
  clave:'Al oxigenarse, la hemoglobina LIBERA PROTONES: se desprotona. Es el efecto Bohr leído al revés.',
  exp:'La hemoglobina es una proteína *alostérica* y todo su comportamiento se entiende como un equilibrio entre dos conformaciones: la forma *T* o tensa, de baja afinidad, y la forma *R* o relajada, de alta afinidad. Cuando el oxígeno se une, la molécula bascula hacia la forma R y, en ese cambio, *rompe los puentes salinos* que estabilizaban la forma T y *libera los protones* que participaban en ellos: por eso la oxigenación produce *desprotonación*. Es la lectura inversa del *efecto Bohr*, que suele enunciarse al revés: en los tejidos, donde hay más CO2 y más protones, estos se unen a la hemoglobina, la estabilizan en forma T y *facilitan la liberación de oxígeno* justo donde hace falta; en el pulmón ocurre lo contrario. Los distractores permiten repasar el resto: la curva de disociación es *sigmoidea*, no hiperbólica, precisamente por la cooperatividad entre las cuatro subunidades; el hierro se mantiene como *Fe2+* y su oxidación a Fe3+ da *metahemoglobina*, incapaz de transportar oxígeno; el *2,3-bisfosfoglicerato* estabiliza la forma T y por tanto *dificulta* la unión de oxígeno, desplazando la curva a la derecha; y la unión al hierro es de *coordinación*, no covalente.',
  no:{0:'La curva es SIGMOIDEA por la cooperatividad entre subunidades; la hiperbólica es la de la mioglobina.',1:'El hierro se mantiene como Fe2+: su oxidación a Fe3+ genera metahemoglobina, que no transporta oxígeno.',3:'El 2,3-bisfosfoglicerato estabiliza la forma T y DIFICULTA la unión de oxígeno.',4:'La unión al hierro es de coordinación reversible, no covalente, y el hierro es ferroso.'},
  trampa:'Se recuerda el efecto Bohr solo en un sentido. Si los protones expulsan oxígeno en el tejido, el oxígeno expulsa protones en el pulmón.',
  dx:[],
  obj:'Explicar el efecto Bohr y la alosteria de la hemoglobina.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Lehninger, Principios de Bioquímica.'
},
'MIR-2013-P136': {
  esp:'Ciencias Básicas', tema:'Bioquímica', sub:'Cadena respiratoria mitocondrial',
  clave:'Antimicina y cianuro bloquean CITOCROMOS de la cadena respiratoria: por eso la célula no puede usar el oxígeno.',
  exp:'La *cadena de transporte electrónico* mitocondrial tiene cuatro complejos y sus inhibidores clásicos se preguntan siempre por parejas. La *rotenona* y el amital bloquean el *complejo I*. El *malonato* inhibe la succinato deshidrogenasa del *complejo II*. La *antimicina A* bloquea el *complejo III*, en concreto el citocromo b-c1. Y el *cianuro*, junto con el *monóxido de carbono* y la *azida*, bloquea el *complejo IV*, la citocromo c oxidasa. Todos ellos comparten diana: los *citocromos*, proteínas con grupo hemo que transportan electrones. Y todos comparten consecuencia: al detenerse el flujo de electrones se detiene el bombeo de protones, se colapsa el gradiente y cesa la síntesis de ATP, con lo que la célula se ve obligada a recurrir al metabolismo *anaerobio*. De ahí el hallazgo clínico que ya vimos en la intoxicación por humo de incendio: *acidosis láctica intensa* con oxígeno arterial y saturación normales, porque el oxígeno está disponible pero la célula no puede utilizarlo; es la llamada *hipoxia histotóxica*, y la sangre venosa aparece anormalmente oxigenada.',
  no:{0:'El transporte de ácidos grasos a la mitocondria lo bloquea el malonil-CoA a través de la carnitina palmitoiltransferasa, no estos tóxicos.',2:'La glucólisis es citoplásmica y no depende de citocromos; de hecho es la vía que se activa al bloquearse la cadena.',3:'Las deshidrogenasas del ciclo de Krebs no son la diana; el ciclo se frena de forma secundaria al acumularse NADH.',4:'La replicación del ADN no tiene relación con estos tóxicos.'},
  trampa:'Se busca un mecanismo complicado. Cianuro y antimicina hacen lo mismo: cortan la cadena respiratoria y obligan a la célula a fermentar.',
  dx:['Intoxicación por cianuro','Intoxicación por monóxido de carbono','Acidosis láctica'],
  obj:'Situar los inhibidores clásicos en los complejos de la cadena respiratoria.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Lehninger, Principios de Bioquímica.'
},
'MIR-2013-P218': {
  esp:'Ciencias Básicas', tema:'Inmunología', sub:'Reacciones de hipersensibilidad',
  clave:'La hipersensibilidad tipo III es la de los INMUNOCOMPLEJOS que se depositan en los tejidos y activan el complemento.',
  exp:'La clasificación de *Gell y Coombs* ordena las cuatro reacciones de hipersensibilidad y conviene tenerla completa porque explica media inmunología clínica. La *tipo I* es *inmediata*, mediada por *IgE* unida a mastocitos y basófilos, que al reconocer el alérgeno degranulan liberando histamina: es la anafilaxia, el asma alérgico, la rinoconjuntivitis y la urticaria. La *tipo II* es *citotóxica*, mediada por *IgG o IgM* dirigidas contra antígenos de la superficie celular, que destruyen la célula por complemento o citotoxicidad: anemia hemolítica autoinmune, púrpura trombocitopénica, Goodpasture, miastenia gravis. La *tipo III* es la de los *inmunocomplejos*, que circulan y se *depositan* en glomérulo, articulaciones, piel y vasos, activando el complemento y atrayendo neutrófilos: enfermedad del suero, lupus, glomerulonefritis postinfecciosa, vasculitis crioglobulinémica y fenómeno de Arthus. Y la *tipo IV* es la *retardada*, mediada por *linfocitos T* y macrófagos, sin anticuerpos y con un plazo de 48 a 72 horas: el Mantoux, la dermatitis de contacto, el rechazo de trasplante y la reacción granulomatosa.',
  no:{0:'La activación de mastocitos define la hipersensibilidad tipo I, mediada por IgE.',2:'La activación de macrófagos con linfocitos T corresponde a la tipo IV o retardada.',3:'El infiltrado de neutrófilos es una consecuencia del depósito de inmunocomplejos, no el mecanismo que define el tipo.',4:'Las reacciones de citotoxicidad directa sobre la célula definen la tipo II.'},
  trampa:'Se confunden la tipo II y la tipo III. Regla: en la II el anticuerpo ataca a la célula misma; en la III el complejo ya formado viaja y se deposita.',
  dx:[],
  obj:'Clasificar las reacciones de hipersensibilidad de Gell y Coombs.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Abbas, Inmunología Celular y Molecular.'
},
'MIR-2013-P231': {
  esp:'Ciencias Básicas', tema:'Biología molecular', sub:'Factores de transcripción',
  clave:'Los factores de transcripción se unen al ADN, no al ARN: reconocen secuencias reguladoras y controlan qué genes se expresan.',
  exp:'Los *factores de transcripción* son proteínas que reconocen *secuencias específicas del ADN* —promotores, potenciadores o enhancers, y silenciadores— y regulan desde ahí el reclutamiento de la ARN polimerasa y, con ello, *qué genes se transcriben y con qué intensidad*. Se unen al surco mayor de la doble hélice a través de dominios estructurales característicos que conviene reconocer: *dedos de zinc*, *hélice-giro-hélice*, *cremallera de leucina* y *hélice-bucle-hélice*. Su importancia clínica es enorme, porque son el punto donde convergen muchas señales: los *receptores hormonales nucleares* de esteroides, hormona tiroidea y vitamina D son literalmente factores de transcripción activados por su ligando, y buena parte de los oncogenes —*MYC*, *FOS*, *JUN*— y de los supresores como *p53* también lo son. Los distractores repasan piezas vecinas: las *histonas* forman el nucleosoma y empaquetan el ADN, la *metilación* del ADN es otro mecanismo epigenético de regulación distinto, y las proteínas que se unen al *ARN* son las que regulan su estabilidad, su procesamiento y su traducción, no la transcripción.',
  no:{0:'Las histonas empaquetan el ADN en nucleosomas; los factores de transcripción reconocen secuencias, no histonas.',1:'Se unen al ADN, no al ARN: las proteínas de unión a ARN regulan procesamiento y traducción.',3:'Quienes se organizan en nucleosomas son las histonas junto con el ADN.',4:'La metilación del ADN es un mecanismo epigenético distinto, ejecutado por metiltransferasas.'},
  trampa:'Se confunde transcripción con traducción. Si el factor regula la síntesis de ARN, necesariamente se une al ADN, que es el molde.',
  dx:[],
  obj:'Definir los factores de transcripción y su unión a secuencias del ADN.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Alberts, Biología Molecular de la Célula.'
},
'MIR-2013-P77': {
  esp:'Ciencias Básicas', tema:'Genética', sub:'Enfermedades lisosomales',
  clave:'Las MUCOPOLISACARIDOSIS son enfermedades de depósito LISOSOMAL: falla una hidrolasa del lisosoma y se acumula el sustrato.',
  exp:'Las *enfermedades lisosomales* comparten un mismo esquema: falta una *hidrolasa ácida* del lisosoma, el sustrato que debía degradarse se *acumula* progresivamente dentro del orgánulo y la célula se llena de material de depósito. De ahí su clínica común: *visceromegalia*, afectación ósea, rasgos faciales toscos, y con frecuencia deterioro neurológico progresivo, con un curso que empeora con la edad. Las *mucopolisacaridosis* son el ejemplo del enunciado: se acumulan *glucosaminoglucanos* por déficit de las enzimas que los degradan, y dan cuadros como el *síndrome de Hurler* o el de *Hunter*, con disostosis múltiple, opacidad corneal, hepatoesplenomegalia y afectación valvular. A su lado están las *esfingolipidosis* —Gaucher, Fabry, Niemann-Pick, Tay-Sachs, Krabbe—, las *glucogenosis tipo II* o enfermedad de Pompe, y las oligosacaridosis. Los distractores corresponden a defectos de otra naturaleza: el *GLUT2* y los *transportadores de aminoácidos básicos* son fallos de *transporte de membrana* —el segundo produce la cistinuria—, y la *lipasa sensible a hormonas* y la *lipoproteína lipasa* son enzimas *citosólicas o endoteliales*, no lisosomales; el déficit de LPL produce hipertrigliceridemia grave con pancreatitis.',
  no:{0:'El déficit de GLUT2 es un defecto de transporte de membrana, el síndrome de Fanconi-Bickel.',1:'La lipasa sensible a hormonas es citosólica y moviliza los triglicéridos del adipocito.',2:'La lipoproteína lipasa es endotelial: su déficit produce hipertrigliceridemia grave, no depósito lisosomal.',3:'El defecto de transportadores de aminoácidos básicos produce cistinuria, un trastorno del transporte tubular.'},
  trampa:'Se agrupan todos los errores del metabolismo como si fueran iguales. Lo lisosomal se reconoce por el depósito progresivo con visceromegalia.',
  dx:['Mucopolisacaridosis','Esfingolipidosis','Glucogenosis'],
  obj:'Reconocer las mucopolisacaridosis dentro de las enfermedades de depósito lisosomal.',
  ref:'Examen FIR 2013, Ministerio de Sanidad de España. Contrastado con Harrison, 21.ª ed., capítulo de errores congénitos del metabolismo.'
}

});
